-- =====================================================================
--  Base « acnh_site » complète : les 10 tables et leurs données (5 645 lignes)
--  Projet transversal SQL : Animal Crossing New Horizons (EPSI B1)
--
--  À importer dans phpMyAdmin (onglet Importer) : la base acnh_site est
--  supprimée si elle existe, puis recréée avec les mêmes données que la migration.
-- =====================================================================

SET NAMES utf8mb4;

DROP DATABASE IF EXISTS acnh_site;
CREATE DATABASE acnh_site CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE acnh_site;

-- ENGINE=InnoDB : sous Wamp, le moteur par défaut est MyISAM, qui ne vérifie pas les clés étrangères.


-- ---------------------------------------------------------------------
-- 1. CRÉATURES (poissons et insectes)
-- ---------------------------------------------------------------------
CREATE TABLE lieu (
  id_lieu  INT          NOT NULL AUTO_INCREMENT,
  nom_lieu VARCHAR(120) NOT NULL,
  PRIMARY KEY (id_lieu),
  UNIQUE (nom_lieu)
) ENGINE=InnoDB;

CREATE TABLE creature (
  id_creature          INT         NOT NULL AUTO_INCREMENT,
  id_lieu              INT         NOT NULL,
  type_creature        VARCHAR(10) NOT NULL,
  numero_encyclopedie  INT         NOT NULL,
  nom_creature         VARCHAR(50) NOT NULL,
  prix_vente_creature  INT         NOT NULL,
  ombre                VARCHAR(20) NULL,
  difficulte           VARCHAR(20) NULL,
  meteo                VARCHAR(20) NOT NULL,
  captures_requises    INT         NOT NULL,
  description          TEXT        NOT NULL,
  phrase_capture       TEXT        NOT NULL,
  nom_fichier_creature VARCHAR(40) NOT NULL,
  PRIMARY KEY (id_creature),
  UNIQUE (type_creature, nom_creature),
  UNIQUE (type_creature, numero_encyclopedie),
  FOREIGN KEY (id_lieu) REFERENCES lieu (id_lieu),
  CHECK (type_creature IN ('poisson', 'insecte')),
  CHECK (prix_vente_creature >= 0)
) ENGINE=InnoDB;

-- Une ligne = une plage horaire d'un mois, dans un hémisphère.
-- La créature est là de heure_debut (incluse) à heure_fin (exclue).
-- Une plage qui passe minuit est enregistrée en deux lignes : 21 h -> 4 h donne 21 -> 24 et 0 -> 4.
CREATE TABLE disponibilite (
  id_disponibilite INT     NOT NULL AUTO_INCREMENT,
  id_creature      INT     NOT NULL,
  hemisphere       CHAR(2) NOT NULL,
  mois             INT     NOT NULL,
  heure_debut      INT     NOT NULL,
  heure_fin        INT     NOT NULL,
  PRIMARY KEY (id_disponibilite),
  UNIQUE (id_creature, hemisphere, mois, heure_debut),
  FOREIGN KEY (id_creature) REFERENCES creature (id_creature),
  CHECK (hemisphere IN ('NH', 'SH')),
  CHECK (mois BETWEEN 1 AND 12),
  CHECK (heure_debut >= 0 AND heure_debut < heure_fin AND heure_fin <= 24)
) ENGINE=InnoDB;


-- ---------------------------------------------------------------------
-- 2. MEUBLES ET SAISONS
-- ---------------------------------------------------------------------
CREATE TABLE categorie (
  id_categorie  INT         NOT NULL AUTO_INCREMENT,
  nom_categorie VARCHAR(30) NOT NULL,
  PRIMARY KEY (id_categorie),
  UNIQUE (nom_categorie)
) ENGINE=InnoDB;

CREATE TABLE meuble (
  id_meuble            INT          NOT NULL AUTO_INCREMENT,
  id_categorie         INT          NOT NULL,
  nom_meuble           VARCHAR(100) NOT NULL,
  prix_achat           INT          NULL,
  prix_vente_meuble    INT          NOT NULL,
  bricolable           BOOLEAN      NOT NULL,
  personnalisable      BOOLEAN      NOT NULL,
  taille               VARCHAR(10)  NOT NULL,
  exterieur            BOOLEAN      NOT NULL,
  etiquette            VARCHAR(40)  NOT NULL,
  serie                VARCHAR(40)  NULL,
  catalogue            VARCHAR(20)  NOT NULL,
  points_hha           INT          NOT NULL,
  version_ajout_meuble VARCHAR(10)  NOT NULL,
  id_interne           INT          NOT NULL,
  PRIMARY KEY (id_meuble),
  UNIQUE (id_interne),
  FOREIGN KEY (id_categorie) REFERENCES categorie (id_categorie),
  CHECK (catalogue IN ('For sale', 'Not for sale', 'Not in catalog', 'Seasonal'))
) ENGINE=InnoDB;

-- Une saison ou un événement du jeu (Halloween, Toy Day, Summer…)
CREATE TABLE saison (
  id_saison   INT         NOT NULL AUTO_INCREMENT,
  nom_saison  VARCHAR(80) NOT NULL,
  type_saison VARCHAR(30) NOT NULL,
  PRIMARY KEY (id_saison),
  UNIQUE (nom_saison)
) ENGINE=InnoDB;

-- Table associative : un meuble peut être proposé pendant plusieurs saisons,
-- et une saison propose plusieurs meubles.
CREATE TABLE proposer (
  id_meuble INT NOT NULL,
  id_saison INT NOT NULL,
  PRIMARY KEY (id_meuble, id_saison),
  FOREIGN KEY (id_meuble) REFERENCES meuble (id_meuble),
  FOREIGN KEY (id_saison) REFERENCES saison (id_saison)
) ENGINE=InnoDB;


-- ---------------------------------------------------------------------
-- 3. VILLAGEOIS
-- ---------------------------------------------------------------------
CREATE TABLE espece (
  id_espece  INT         NOT NULL AUTO_INCREMENT,
  nom_espece VARCHAR(30) NOT NULL,
  PRIMARY KEY (id_espece),
  UNIQUE (nom_espece)
) ENGINE=InnoDB;

CREATE TABLE personnalite (
  id_personnalite  INT         NOT NULL AUTO_INCREMENT,
  nom_personnalite VARCHAR(20) NOT NULL,
  PRIMARY KEY (id_personnalite),
  UNIQUE (nom_personnalite)
) ENGINE=InnoDB;

CREATE TABLE villageois (
  id_villageois            INT         NOT NULL AUTO_INCREMENT,
  id_espece                INT         NOT NULL,
  id_personnalite          INT         NOT NULL,
  nom_villageois           VARCHAR(30) NOT NULL,
  genre                    VARCHAR(10) NOT NULL,
  sous_type                CHAR(1)     NOT NULL,
  jour_anniversaire        INT         NOT NULL,
  mois_anniversaire        INT         NOT NULL,
  phrase_fetiche           VARCHAR(50) NOT NULL,
  chanson_preferee         VARCHAR(50) NOT NULL,
  citation_preferee        TEXT        NOT NULL,
  version_ajout_villageois VARCHAR(10) NOT NULL,
  nom_fichier_villageois   VARCHAR(20) NOT NULL,
  PRIMARY KEY (id_villageois),
  UNIQUE (nom_villageois),
  FOREIGN KEY (id_espece) REFERENCES espece (id_espece),
  FOREIGN KEY (id_personnalite) REFERENCES personnalite (id_personnalite),
  CHECK (genre IN ('Male', 'Female')),
  CHECK (jour_anniversaire BETWEEN 1 AND 31 AND mois_anniversaire BETWEEN 1 AND 12)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- DONNÉES
-- ---------------------------------------------------------------------
-- SET FOREIGN_KEY_CHECKS = 0 : pas de vérification des clés étrangères pendant le chargement,
-- car les tables sont remplies dans l'ordre alphabétique (creature avant lieu).
-- Ces données ont déjà été vérifiées par MySQL pendant la migration (migration/import.php).
SET FOREIGN_KEY_CHECKS = 0;
INSERT INTO `categorie` (`id_categorie`, `nom_categorie`) VALUES (4,'Ceiling Decor'),(1,'Housewares'),(2,'Miscellaneous'),(3,'Wall-mounted');
INSERT INTO `creature` (`id_creature`, `id_lieu`, `type_creature`, `numero_encyclopedie`, `nom_creature`, `prix_vente_creature`, `ombre`, `difficulte`, `meteo`, `captures_requises`, `description`, `phrase_capture`, `nom_fichier_creature`) VALUES (1,1,'poisson',56,'anchovy',200,'Small','Very Easy','Any weather',0,'There are more than 140 species of anchovy, but they do all have some things in common. They are small and feed by simply swimming with their mouths open to filter food particles from the sea. (In my sleepier moments, I sometimes wish I could do that...)','I caught an anchovy! Stay away from my pizza!','Fish81'),(2,2,'poisson',36,'angelfish',3000,'Small','Easy','Any weather',20,'The angelfish is truly a beautiful creature. Just look at the elegance of those fins! Despite the name, however, these lovelies are known to be rather aggressive. They\'ve no qualms about relentlessly pursuing fish much smaller than themselves! Why, they even attack their own kin! It seems no fish is safe around these \"angelic\" bullies. It makes one wonder who comes up with these names. Appearances— and names— can be deceiving.','I caught an angelfish! That other fish told me to do it!','Fish30'),(3,2,'poisson',44,'arapaima',10000,'XX-Large','Very Hard','Any weather',50,'The stately arapaima is quite large. Indeed, it is among the largest freshwater fish there are. Furthermore, these fascinating fish make quite the family unit. That is to say, male arapaimas protect their young by holding them gently in their mouths. Meanwhile, female arapaimas swim circles around these full-mouthed fathers fending off predators. It simply goes to show that cold-blooded creatures can be heartwarming too.','I caught an arapaima! How did it get here? Arapaiknow!','Fish36'),(4,2,'poisson',41,'arowana',10000,'Large','Very Hard','Any weather',50,'It would seem your angling expertise knows no bounds! This beauteous arowana fetches a pretty Bell, though I\'d venture to say that its true price is beyond measure. The arowana is an excellent jumper. Some have been seen  leaping six feet out of the water, eh wot! Alas, it has also been on the endangered-species list for some time. It\'s up to us to do all we can to help preserve such magnificent creatures for the years to come.','I caught an arowana! I\'d make a joke, but I don\'t \'wana.','Fish33'),(5,1,'poisson',58,'barred knifejaw',5000,'Medium','Hard','Any weather',20,'Wonderful! I would love nothing more! The barred knifejaw, also called the striped beakfish, is a lovely fish with a distinctive striped pattern. It is reportedly also a very curious fish in that it has been known to approach swimmers to \"greet\" them. They also tend to be good at avoiding fishing hooks, so well done on outwitting this one!','I caught a barred knifejaw! They must have a hard time eating!','Fish47'),(6,1,'poisson',79,'barreleye',15000,'Small','Very Hard','Any weather',100,'The barreleye is a deep-sea fish with protuberant eyes and a clear head, so some of its organs are... visible. At first blush, a transparent head seems absurd, but there is a reason: so it can see things directly above! But I must confess - the more I learn about deep-sea fish, the happier I am to live on dry land, wot.','I caught a barreleye! Like eyeing fish in a barrel!','Fish84'),(7,2,'poisson',37,'betta',2500,'Small','Hard','Any weather',20,'The betta has long fins and beautiful coloring. It is a tropical fish popular in decorative aquariums. They\'re very territorial and will fight to complete exhaustion, so aquarists must keep them carefully. Rarely do such beauty and violence commingle outside the rowdiest of sunset-viewing parties.','I caught a betta! I betta not drop it!','Fish77'),(8,2,'poisson',1,'bitterling',900,'X-Small','Hard','Any weather',0,'Bitterlings hide their eggs inside large bivalves—like clams—where the young can stay safe until grown. The bitterling isn\'t being sneaky. No, their young help keep the bivalve healthy by eating invading parasites! It\'s a wonderful bit of evolutionary deal making, don\'t you think? Each one keeping the other safe... Though eating parasites does not sound like a happy childhood... Is that why the fish is so bitter?','I caught a bitterling! It\'s mad at me, but only a little.','Fish0'),(9,2,'poisson',22,'black bass',400,'Large','Medium','Any weather',0,'The black bass is a formidably strong fish and, as such, is a common target for sport anglers. In some areas, there are even those who professionally catch just black bass! Yet in other areas where they are NOT native, they are considered an ecological nuisance. Invasive, even. One cannot help but wonder who is to blame for their invasion, hoo.','I caught a black bass! The most metal of all fish!','Fish19'),(10,1,'poisson',54,'blowfish',5000,'Medium','Medium','Any weather',20,'As you may know, blowfish carry a deadly poison and are among the most toxic creatures on earth. What you may not have known is that poison and spines are not the limit of this animal\'s defenses! A predator that tries to swallow a blowfish before it inflates can find itself quickly choking. To be honest, if said predator can get past poison, spines, AND choking hazards, I feel they\'ve earned a meal.','I caught a blowfish! I\'m blown away!','Fish73'),(11,3,'poisson',67,'blue marlin',10000,'XX-Large','Very Hard','Any weather',50,'The blue marlin has a distinctive angular shape and no scales. It is an unusual relative of the tuna. These mighty fish can exceed 13 feet from bill to tail. Some accounts even have it fighting with whales! No wonder it\'s a popular target for sport fishing: unlike most fish, it seems like a worthy opponent.','I caught a blue marlin! Listen to this fish. it\'s got a point.','Fish58'),(12,2,'poisson',20,'bluegill',180,'Small','Very Easy','Any weather',0,'The bluegill is incredibly common. A bit too common, depending upon where you are. They eat anything that fits in their mouths and are highly adaptable. The bane of fishermen in some areas, bluegill is often the only fish to be caught! But looking in its wee beady eyes, I must say I see no ill will in it...','I caught a bluegill! Do you think it calls me \"pinklung\"?','Fish17'),(13,1,'poisson',51,'butterfly fish',1000,'Small','Easy','Any weather',0,'Ah, the butterfly fish is just charming with its beautiful colors and elegant movements. I refer to it as a butterfly fish, but it\'s actually a grouping in which there are over 100 types! These beautiful aquatic friends swim in schools amid coral, fluttering back and forth with the tides. The sheer awe one must experience when witnessing such a sight. It must be a dream! So much better than actual butterflies...','I caught a butterfly fish! Did it change from a caterpillar fish?','Fish42'),(14,4,'poisson',5,'carp',300,'Large','Very Easy','Any weather',0,'Oh, the carp... have you ever seen their teeth? For your sake, I hope you have not! Carp have teeth in their throat strong enough to crunch on hard things like shells and fingers! A good rule of thumb when dealing with other species is to keep your fingers out of their mouths. Although, having neither thumbs nor fingers, I am quite safe from this little fellow!','I caught a carp! If I catch another, they can carpool!','Fish5'),(15,4,'poisson',18,'catfish',800,'Large','Medium','Any weather',0,'Catfish don\'t have scales and are rather slimy. Believe it or not, this slime helps them breathe! Some species of catfish are nocturnal, and they\'ll feed on almost anything. They use a suctioning action to pull in their food. Did I mention they can grow as large as you or I?','I caught a catfish! I\'m more of a dogfish person...','Fish14'),(16,5,'poisson',28,'char',3800,'Medium','Hard','Any weather',20,'The char is one of the bigger first around the world, and, in the world of fish, that\'s quite an accomplishment! They are territorial predators, and therefore must constantly defend their \'turf\' from others. So when you see a large char like this one, it is likely a skilled fighter and veteran of many battles. My feathers! I hope it never has cause to go into battle with me!','I caught a char! Now I\'m gonna sit on it!','Fish24'),(17,5,'poisson',27,'cherry salmon',1000,'Medium','Medium','Any weather',0,'The cherry salmon is related to the salmon, and is known for its distinctive pattern of \"polka dots\". There polka dots disappear as they mature, but ONLY in the first of certain geographic regions. Pity the poor researchers that must make sense of the cherry salmon\'s fickle fashion sense.','I caught a cherry salmon! It\'s the perfect topper for a marlin sundae!','Fish23'),(18,1,'poisson',49,'clown fish',650,'X-Small','Medium','Any weather',0,'Few can deny the delightful qualities of the clown fish. These vibrant fishes make their home among venomous anemones. It\'s a mutually beneficial arrangement. The clown fish finds safety in the anemone\'s wriggling arms, as well as leftover scraps of food. In return, clown fish ward off parasites and predators for the anemone. Thus these colorful fish remind us of the importance of maintaining good cheer among our roommates.','I caught a clown fish! How many can fit in a carfish?','Fish40'),(19,1,'poisson',80,'coelacanth',15000,'XX-Large','Very Hard','Rain only',100,'The coelacanth is a deep-sea fish that has been around since the age of the dinosaurs. They were long thought extinct, so when living specimens were discovered, it was quite a shock! Now I\'ll just have to figure out where in the museum to display it— fish or fossils!','Blast from the past! I caught a coelacanth! Think positive! Be a coela-CAN!','Fish63'),(20,4,'poisson',11,'crawfish',200,'Small','Very Easy','Any weather',0,'Ohoo! So you have found a crawfish. Neither crab nor lobster, crawfish evolved in an interesting manner. Beware their fearsome pinchy pinchers! Behold their many legs! I say! It is a big bug-like, eh wot...The more I look at it, the more unsettled I feel... Let\'s be done with this and never speak of it again, shall we?','I caught a crawfish! Or else it\'s a lobster and I\'m a giant!','Fish10'),(21,2,'poisson',3,'crucian carp',160,'Small','Very Easy','Any weather',0,'I wonder... Do you know how to tell the difference between a crucian carp and a standard-issue carp? It\'s quite easy to tell the two apart... One must simply locate the barbels. Or, rather, the lack of them! And just what is a barbel, you ask? Well, a barbel looks a little something like a mustache. A run-of-the-mill carp will sport this unsightly \"facial hair,\" while a crucian carp is considerably better groomed! I tried to grow a mustache when I was younger. It never did fill in quite right... All for the best in the end, as mustaches go so much better with noses than with beaks!','I caught a crucian carp! My skills are sharp!','Fish2'),(22,1,'poisson',61,'dab',300,'Medium','Easy','Any weather',0,'The dab is a flatfish that bears some resemblance to the olive flounder, though their mouths are different. Personally, I am morbidly fascinated by each fish\'s eye placement. The dab\'s eyes are both on its right side, while the olive flounder\'s are on the left. These fish spend lots of time lying on their sides in the sand, so the odd eye placement makes some sense... But its-how can I put this? Creepy? Viscerally disturbing? Profoundly upsetting to fans of symmetry?','I caught a dab! Not bad!','Fish50'),(23,2,'poisson',4,'dace',240,'Medium','Easy','Any weather',0,'Dace are shiny little fish that enjoy freshwater streams with gravelly bottoms and plenty of sunlight. What a fishy paradise...until the larger fish move in and begin eating the dace! Sadly, the shiny dace are easy for other fish to spot, which makes them a popular snack. However, this particular specimen here has no need to worry. There\'s a strict \"No Eating Your Neighbor\" policy at this institution.','I caught a dace! Hope I have some space!','Fish3'),(24,2,'poisson',42,'dorado',15000,'X-Large','Very Hard','Any weather',100,'Woo-hoo! So shiny! This massive fish\'s name, dorado, means \"golden\" in Spanish— a fitting title. They are also quite valuable, I understand. I congratulate you on your top-notch angling! They are rather large, eh wot? It makes one wonder what all they might feed on... Fowl, perhaps?! One quivers at the very thought! Well, it\'ll be safe behind glass, no doubt. Quite safe, hoo','I caught a dorado! I say \"dorado,\" you say \"doraydo.\"','Fish34'),(25,1,'poisson',77,'football fish',2500,'Large','Very Easy','Any weather',20,'The football fish is a strange and grotesque deep-sea fish with a lantern-like light on its forehead. Its light is apparently powered by luminous bacteria and other glowing microorganisms. One theory says it can spray these luminescent sidekicks when prey approaches in order to dazzle them...The deep contains many mysteries...as well as some things that are just sort of odd and off-putting.','I caught a football fish! Some countries call it a soccer fish!','Fish56'),(26,2,'poisson',16,'freshwater goby',400,'Small','Very Easy','Any weather',0,'The freshwater goby is an unassuming specimen. But beneath that calm, fish exterior, true gluttony resides! It will eat anything that will fit in its mouth...And its mouth is quite the gaping maw, so I recommend you refrain from drawing attention to yourself!','I caught a freshwater goby! Time to go bye-bye!','Fish12'),(27,4,'poisson',15,'frog',120,'Small','Easy','Any weather',0,'I understand that frogs converse with fellow frogs through a number of varied calls, as it were. Ribbit! My prince has arrived! Gribbit riiibbit! This pond is tragic! Ribbity rib\'t! I think you\'re splendid! Hoo hoo, of course I have no clue what they\'re saying, but I like to think if I practice enough, I might!','I caught a frog! Or it\'s a new neighbor...and I have some apologizing to do.','Fish11'),(28,4,'poisson',43,'gar',6000,'X-Large','Hard','Any weather',50,'Hoo hoo! So you have snagged a gar. Did you know this beastly fish can grow up to nine feet long? Indeed, the gar is a remnant of times long past-a living fossil, if you will. It not only has sharp teeth and armor-like scalesn, it has the ability to take breaths of air as well! Ah, to look upon this unusual fish is to get a glimpse of our prehistoric past.','I caught a gar! Yar! It\'s a gar! Har har!','Fish35'),(29,4,'poisson',19,'giant snakehead',5500,'Large','Hard','Any weather',50,'The giant snakehead is quite a sight to behold, wot! One glance conjures up visions of its namesake. This resilient creature can even find a home in the mud, where it is able to breathe. As a matter of fact, it dislikes cold weather, so during wintertime the mud serves as its temporary home. I hear that they eat anything that swims past their head. While odd, I feel a sense of owlship with them.','I caught a giant snakehead! Um...but I asked for a medium?','Fish16'),(30,3,'poisson',68,'giant trevally',4500,'X-Large','Very Hard','Any weather',20,'The giant trevally, as befits its name, can reach six feet in length and 180 pounds! Its size and strength have made it a favored opponent for anglers since time immemorial. They are also ingenious hunters, sometimes taking advantage of other predators to distract their prey. There have even been documented cases of them attacking —gulp— birds.','I caught a giant trevally! Yeah, I\'m pretty well-trevalled.','Fish70'),(31,5,'poisson',29,'golden trout',15000,'Medium','Very Hard','Any weather',100,'The golden trout is a beautifully colored fish that can only live in very clean waters. They are difficult to come across since they are found only in high mountain streams. As a side note, I find it much easier to appreciate fish that aren\'t such prima donnas about everything.','I caught a golden trout! But the real treasure? Friendship.','Fish79'),(32,4,'poisson',7,'goldfish',1300,'X-Small','Easy','Any weather',0,'Goldfish are so cute and delicate... but do you know how big they can get? Why, they can grow up to... a foot in length! Well, sometimes. The size of the tank they\'re kept in tends to restrict their growth. And just how big will this goldfish get in our large museum tank? I look forward to finding out!','I caught a goldfish! It\'s worth its weight in fish!','Fish7'),(33,1,'poisson',74,'great white shark',15000,'X-Large w/Fin','Very Hard','Any weather',50,'Great white sharks are obviously known first and foremost for their biting. They are masters of the craft! They do lose teeth regularly through biting-related activities, but, luckily, those teeth grow back quickly. In fact, their missing teeth can be regrown in a single day. Just imagine their tooth-fairy-related income!','I caught a great white shark! Watch out for its jaws!','Fish62'),(34,2,'poisson',34,'guppy',1300,'X-Small','Easy','Any weather',0,'Oh my! Would you look at that! Such a beautiful, snazzy little fellow that guppy is! The shape and coloration of guppy fins are all unique. Quite eye-catching, I must say. Do you imagine they host contests for \"most snazzy\"? And...do you suppose I might receive an invite?','I caught a guppy! Welcome to the team, newbie!','Fish29'),(35,1,'poisson',73,'hammerhead shark',8000,'X-Large w/Fin','Hard','Any weather',20,'The hammerhead shark is known for its distinctive, hammer-shaped head, hence the name. Er, obviously. Anyhoot, this oddly shaped head allows the beast to see 360 degrees around itself, from top to bottom. Imagine being able to see so widely! You could check for untied shoelaces AND imminent rain simultaneously!','I caught a hammerhead shark! I hit the nail on the head!','Fish61'),(36,1,'poisson',57,'horse mackerel',150,'Small','Very Easy','Any weather',0,'Supposedly the horse mackerel derives its name from a-false-myth about its strengh as a swimmer. The gist of it is that these fish are so powerful underwater that smaller fish can ride them as steeds! It\'s absurd, of course. Where would these alleged fish jockeys attach a saddle, much less horseshoes? One does wish that people would construct their legends with a BIT more scientific plausibility!','I caught a horse mackerel! Of course, Mack...er...el.','Fish46'),(37,4,'poisson',10,'killifish',300,'X-Small','Medium','Any weather',0,'Ah, the magnificent killifish! Did you know there are over 1,000 different species? My goodness, what a family tree to keep track of! My own favorite killifish species are the mangrove, which can live on land for weeks, breathing air! And the mummichog, the first fish ever brought to space. I wonder if the killifish you\'ve brought me is related to either of those intrepid explorers?','I caught a killifish! The streams are safe again.','Fish9'),(38,6,'poisson',32,'king salmon',1800,'X-Large','Hard','Any weather',20,'The king salmon didn\'t get its name for nothing.This stately fish can weigh in at up to 130 pounds! It\'s clear why it\'s referred to as the king of salmon. I imagine even the mightiest net can catch no more than a few at a time.I must say it\'s a miracle to me that you didn\'t get dragged out to sea by this one, wot!','WOO-HOO! I caught a King salmon! Checkmate!','Fish28'),(39,4,'poisson',6,'koi',4000,'Large','Easy','Any weather',20,'Koi are a variety of carp bred for their color mutations...starting more than a thousand years ago! Well, one glance at their impressive coloring tells you that the centuries of effort were worth it. And even today people still selectively breed koi in search of new color combinations! One marvels at the thought of what the koi may look like in another thousand years.','I caught a koi! I don\'t know why it\'s so shy... or such a bad speller...','Fish6'),(40,2,'poisson',17,'loach',400,'Small','Easy','Any weather',0,'Loaches are a large group of bottom-feeding freshwater fish. Because there are so many species, it is difficult to generalize about them all. The one thing they all have in common is perhaps their most unappealing trait; the name \'loach.\' Repellent, isn\'t it? They should have just called it the \'cockloach\' and been done with it, eh wot! Loach...loach... It just tastes terrible in the beak.','I caught a loach! It\'s...looking at me with reproach.','Fish13'),(41,3,'poisson',69,'mahi-mahi',6000,'X-Large','Very Hard','Any weather',50,'The mahi-mahi is an ocean fish known for its wide, somewhat-cute face. It can reach over six feet long. It is known by different names including \"dolphinfish,\" even though it has no relation to dolphins. They live in only in warm, tropical waters...which perhaps explains the relaxed, happy look on their faces.','I caught a mahi-mahi! It\'s all mahine-mahine.','Fish82'),(42,2,'poisson',33,'mitten crab',2000,'Small','Hard','Any weather',20,'The mitten crab was named for its impossibly adorable and fuzzy little pincers. These cute crustaceans embark on quite the journey. They\'re first born in brackish waters. Then they mature in freshwater. Finally, they travel to the ocean to create more mitten crabs!Hoo! How I delight in the thought of thousands of tiny mittened crabs scuttling about!','I caught a mitten crab! One more and I\'m ready for winter!','Fish66'),(43,1,'poisson',64,'moray eel',2000,'Long','Easy','Any weather',20,'Despite its rather frightening features, the moray eel is really a very cowardly fish. It lives its life hiding in caves, and will only attack if you\'re looking for a fight. You\'ve heard of a \"bark that is worse than the bite\"? Well, the moray eel has a face that\'s worse than its fight!','I caught a moray eel! When you\'re in love, that\'s a moray!','Fish55'),(44,1,'poisson',52,'Napoleonfish',10000,'XX-Large','Hard','Any weather',50,'Quite the catch you\'ve brought! The stately and debonair Napoleonfish is truly something to behold. Those beady eyes! That bumpy head! That bold blue-green coloring! Alas, this quirky creature is quite endangered due to a variety of factors. Needless to say, we must do our very best to take care of our lumpy friend and its environment.','I caught a Napoleonfish! It\'s not as big as it thinks!','Fish43'),(45,2,'poisson',38,'neon tetra',500,'X-Small','Easy','Any weather',0,'Hoo! Wonderful! The neon tetra is truly a marvel of the tropical-fish world. Just look at how tiny it is! And how very filled with...neon! I imagine its environment must be just as flashy as it is for it to have developed such colors. I wonder how flashy I might be, had I been raised somewhere even half as vibrant?','I caught a neon tetra! Wasn\'t hard to track.','Fish31'),(46,2,'poisson',35,'nibble fish',1500,'X-Small','Medium','Any weather',20,'Nibble fish are best known for their use in a certain skin treatment. This treatment has apparently been used for thousands of years. I have never experienced said treatment because they eat your dead skin with their little toothless mouths! Can you imagine anything so repellent?! Please don\'t ask me any follow-up questions. Hoo.','I caught a nibble fish! Come to think of it, I could use a bite!','Fish67'),(47,1,'poisson',78,'oarfish',9000,'XX-Large','Hard','Any weather',50,'The oarfish is a long, eel-like fish that can supposedly reach up to 36 feet in length. They appear in various legends as things like messengers of the gods. It seems to me a creature like that could explain the myth of massive, ship-crushing sea serpents. It is, of course, well documented that people tend to exaggerate the size of \"the one that got away\".','I caught an oarfish! I hope I catch morefish!','Fish69'),(48,1,'poisson',70,'ocean sunfish',4000,'X-Large w/Fin','Hard','Any weather',20,'The ocean sunfish is a large relative of the blowfish with an unusual shape, like a fish head with a tail. They are a fairly relaxed species, often content to ride where the currents take them. This is fortunate as, otherwise, the sight of a large head coming toward you might be alarming!','I caught an ocean sunfish! Good thing I\'m wearing ocean sunscreen!','Fish60'),(49,1,'poisson',62,'olive flounder',800,'X-Large','Medium','Any weather',0,'Did you know that the olive flounder is the same shape as other fish when it hatches? But as it grows, it gets both wider and flatter, and can reach some three feet long. These flat fish spend much of their lives buried under the sandy ocean floor, waiting for prey to happen by. Imagine the surprise for said prey when they strike. It would be as if your kitchen floor were to bite you.','I caught an olive flounder! That\'s not the pits!','Fish51'),(50,2,'poisson',2,'pale chub',200,'X-Small','Easy','Any weather',0,'The pale chub is a river fish with simple back-and-silver coloring. Interestingly, the males\' coloring becomes most vibrant when he\'s trying to attract a mate! Though normally plain, these fellows really know how to look stylish when they want to. Perhaps I could learn a thing or two from the pale chub...','I caught a pale chub! That name seems a bit judgy...','Fish1'),(51,2,'poisson',24,'pike',1800,'X-Large','Medium','Any weather',20,'The pike has always reminded me a bit of salmon, although a pike can grow rather larger. These brutes can grow to over four feet long, sometimes MUCH over! Hoo hoo! It is carnivorous and preys not only on other fish, but also mammals and some waterfowl. If I were to ever meet one in the water, I would have a most difficult time keeping my wits about me.','I caught a pike! Think a swordfish would be up for a duel?','Fish20'),(52,2,'poisson',40,'piranha',2500,'Small','Very Easy','Any weather',20,'I am not exactly a fan of the piranha, despite knowing that they\'re mostly harmless. But those nasty, pointy teeth, Hoo. These infamous little blighters will attack when in groups. Imagine all of those hundreds of tiny teeth! To think that they\'re floundering about our peaceful waters, just waiting to strike. Well, never fear— I shall keep THIS one under the strictest lock and key, with nary a bathroom break allowed!','I caught a piranha! Sure hope it was the only one!','Fish32'),(53,2,'poisson',25,'pond smelt',400,'Small','Easy','Any weather',0,'For many, thinking of pond smelt inevitably leads to thoughts of ice fishing in frozen rivers and lakes. Ice fishing involves making a round hole in the ice, dropping in your fishing line, and...waiting. Not to rain on anyone else\'s idea of fun, but...well, perhaps I shouldn\'t say anything.','I caught a pond smelt! Whoever smelt it dealt it!','Fish21'),(54,4,'poisson',8,'pop-eyed goldfish',1300,'X-Small','Easy','Any weather',0,'Pop-eyed goldfish have, as the name suggests, huge round eyes. But as babies they look like other goldfish! As they grow, their eyes begin to pop out and they gain their, hoo, distinct appearance... Imagine the poor fish fancier who unknowingly bought one! Their eyes might well pop out just as far!','I got a pop-eyed goldfish! It looks so...surprised!','Fish8'),(55,1,'poisson',55,'puffer fish',250,'Medium','Easy','Any weather',0,'Like its cousin the blowfish, when the puffer fish feels threatened it inflates into a spiky balloon. The biggest difference between them is that the puffer fish is not deadly poisonous like its kin. So while it may look scary, the substantially reduced risk to life and limb makes it much better company.','I caught a puffer fish! I thought you would be tougher, fish!','Fish45'),(56,2,'poisson',39,'rainbowfish',800,'X-Small','Hard','Any weather',0,'The rainbowfish is a tropical fish known for its metallic colors and beautiful fins. There are over 50 different species, each unique and pleasing color. I must say, it does make me wish for feathers of a more exciting hue than \"underbaked brownie.\"','I caught a rainbowfish! Where\'s my pot of goldfish?','Fish80'),(57,4,'poisson',9,'ranchu goldfish',4500,'Small','Hard','Any weather',20,'The ranchu goldfish is a charming relative of the goldfish with a bumpy head and stout, round body. They have ordinary heads when born, but develop impressive rectangular heads after about three years. Supposedly their head shape changes depending on factors like the size of their tank... So ranchu goldfish enthusiasts aim to raise perfectly shaped specimens and work hard to achieve this. Of course, no one asks the ranchu goldfish themselves what shape they want their heads to be...','I caught a ranchu goldfish! But I prefer balsamicu goldfish!','Fish85'),(58,1,'poisson',71,'ray',3000,'X-Large','Easy','Any weather',20,'The ray is an unusually shaped fish with a flat body and a long body, somewhat related to sharks. Seen from the bottom, the mouth on its stomach appears to be smiling, which is objectively adorable. But be cautious—unlike most cute animals, some rays are extremely venomous. BEWARE THE SMILE.','I caught a ray! A few more and I\'ll have a tan!','Fish59'),(59,1,'poisson',60,'red snapper',3000,'Large','Hard','Any weather',0,'Red snapper\' is the common name of dozens of fish species, and I wonder why it is so popular. Are there so many types of fish that are both a shade of red and have a tendency to snap? Were there no other names? What about \'burgundy biter\'? \'Garnet grasper\'? \'Puce pincher\'?','I caught a red snapper! It looks pretty dapper!','Fish49'),(60,1,'poisson',65,'ribbon eel',600,'Long','Hard','Any weather',0,'The ribbon eel is related to the moray eel, though its bright coloration distinguishes it. It also has an unusual plant-like appendage at the tip of its nose that flutters as the creature moves. I like to think of it as having an extremely friendly nose that waves a greeting to those nearby!','I caught a ribbon eel! Can it tie itself into a bow?','Fish71'),(61,2,'poisson',45,'saddled bichir',4000,'Large','Hard','Any weather',20,'What an elegant specimen you\'ve found. The saddled bichir has a look entirely its own. They have poor eyesight, so they use their fine-tuned sniffers to seek out prey. Can you imagine relying solely on your sense of smell to find food? And if one nostril became clogged, would you be unable to tell how far away the scent was?','Wow! A saddled bichir! And me without my tiny riding crop...','Fish68'),(62,6,'poisson',31,'salmon',700,'Large','Medium','Any weather',0,'Ah, salmon! Did you know their coloration is due specifically to their diet? Indeed, this is the case! The more they fill their diet with crustaceans such as krill and shrimp, the deeper shade of pink they are. If they ate a bushel of carrots, might they turn orange?','I caught a salmon! It\'s all upstream from here!','Fish27'),(63,1,'poisson',72,'saw shark',12000,'X-Large w/Fin','Hard','Any weather',50,'As you might expect from the name, the saw shark is a shark with a head that resembles a saw. This unusual appendage is used both to dig potential prey out of the sand and as a weapon against said prey. Given that, it seems like a more appropriate name would have been \"shovel-sword shark,\" eh wot?','I caught a saw shark! You could call it a sea saw!','Fish74'),(64,1,'poisson',59,'sea bass',400,'X-Large','Easy','Any weather',0,'Sea bass is a name given to a variety of different species of saltwater fish. They are a varied bunch with some as small as four inches and some as staggeringly ginormous as eight feet! \'Sea bass\' is a bit pedestrian though. Many species have better names, such as \'redbanded perch.\' Or the delightfully whimsical dusky grouper! Or the potato cod! WILL NO ONE THINK OF THE PINK MAOMAO?!','I caught a sea bass! No, wait- it\'s at least a C+!','Fish48'),(65,1,'poisson',47,'sea butterfly',1000,'X-Small','Easy','Any weather',0,'Such mystery! Such grace! Did you know that the sea butterfly\'s scientific name is Thecosomata? A very rough translation of that is \'shell body.\' Indeed, this illustrious creature is related to snails! However, it reminds me much more of an elegant feathered friend, the way it flies through the water. With such grace in flying, one shouldn\'t wonder if it\'s related to the owl, hoo hoo!','I caught a sea butterfly! Try not to confuse it for a sea moth!','Fish37'),(66,1,'poisson',48,'sea horse',1100,'X-Small','Medium','Any weather',0,'Ah, a favorite of mine, to be sure! The sea horse is such a very unique creature and is indeed a fish! Though, as far as fish go, sea horses are not great swimmers. The sea horse, you see, has but a wee fin on its back, which propels it through water rather poorly. Thus these fish are often found using their prehensile tails to hold tight in amongst the sea grass. And here\'s one final fact for you... Sea horses have no stomach and so must constantly feed to stay alive! Indeed, the life of a land horse sounds far easier than that of the hardworking horse of the sea.','I caught a sea horse! But...where\'s its sea jockey?','Fish39'),(67,2,'poisson',13,'snapping turtle',5000,'Large','Hard','Any weather',0,'The snapping turtle is a large turtle known for its crocodile-like body and long claws. No, wait—it is better known for its ferocious bite, which it can deliver with shocking speed for a turtle. NO, WAIT—it is BEST known for that time one chased me across a parking lot and I had to climb on top of a car.','I caught a snapping turtle! How can it snap without fingers?','Fish78'),(68,2,'poisson',12,'soft-shelled turtle',3750,'Large','Hard','Any weather',20,'The soft-shelled turtle is not one to shy away from biting when provoked. In addition to its powerful bite, this little critter has the ability to breathe both above and below water! It has an unusually long neck which it uses for both breathing and biting. Come to think of it, how did you manage to avoid being bitten? Well, it\'s a fearsome critter, but just look at that face! Rather silly, wot?','I caught a soft-shelled turtle! It\'s more sensitive than other turtles.; I caught a soft-shelled turtle! I should take a shellfie!','Fish65'),(69,1,'poisson',63,'squid',500,'Medium','Easy','Any weather',0,'Well, first off, squids are members of the mollusk family, just like the octopus. Many mollusks like snails and clams have shells, but the squid\'s body is almost completely soft. The exception is a long, narrow bit of hard material going through its main body - the last remnant of its shell. Of course, having your shell INSIDE is not a best practice. Perhaps they lost the owner\'s manual!','I caught a squid! It\'s off the hook!; I caught a squid! I had an inkling I might!; I caught a squid! Do they...not actually \"bloop\"?','Fish52'),(70,5,'poisson',30,'stringfish',15000,'X-Large','Very Hard','Any weather',100,'The stringfish grows slowly, but also lives quite a long time for a fish, with up to 15 years being typical. Consequently, while it takes a while, they can get quite large-perhaps even up to six feet long! The stringfish is perhaps the best embodiment in the fish world of \'slow and steady wins the race\'','OH MY GOSH! I caught a stringfish! Five more and I\'ll have a guitarfish!','Fish26'),(71,6,'poisson',46,'sturgeon',10000,'XX-Large','Very Hard','Any weather',20,'The sturgeon is a large and long-lived fish which has changed little in the last 300 million years. One curious behavior of theirs is leaping high out of the water and falling back in on their sides. The smacking sounds of their re-entry can be heard for up to half a mile away, likely more underwater! No one knows why they do it, but I like to think it\'s their impression of bread popping out of a toaster!','I caught a sturgeon! Wonder if it can perform sturgery...','Fish75'),(72,1,'poisson',76,'suckerfish',1500,'X-Large w/Fin','Very Easy','Any weather',20,'The suckerfish is a curious fish that likes to attach itself with its sucker mouth to larger marine animals. The benefit to the suckerfish is that it gets to eat smaller parasites and dead skin off the host\'s body. Amusingly, some people have used suckerfish on cords to catch large turtles with the fish\'s own suction! I imagine this practice is the cause of some awkward conversations between fish and turtle, eh wot','I caught a suckerfish! I thought it was a shark! Oh, wait - now I get it. \"Sucker\"...','Fish83'),(73,1,'poisson',50,'surgeonfish',1000,'Small','Easy','Any weather',0,'Hoo! Careful, now! These fish are particularly dangerous, despite their seemingly docile appearance. With its saturated blue and yellow tones, the surgeonfish is quite breathtaking. It\'s got to keep up with all the other vibrant fish that live in the coral too, I wager. Quite the competition! Its spine is sharp as a blade, so care must be taken when handling these beauties...','I caught a surgeonfish! Scalpel! Forceps! Fish hook!','Fish41'),(74,2,'poisson',26,'sweetfish',900,'Medium','Hard','Any weather',0,'Sweetfish are the damp heralds of summer! These slippery fellows appear in numbers when it warms up. They hatch in a river, then swim to the ocean. Once mature, they return to the river where they were born. But when they return depends on the river temperature— if it\'s too cold their fishing season will start later. Some even say summer can\'t start without sweetfish despite the KEY role played by the earth\'s axial tilt!','I caught a sweetfish! Hope it\'s not artificially sweet!','Fish22'),(75,4,'poisson',14,'tadpole',100,'X-Small','Easy','Any weather',0,'Undoubtedly you know that tadpoles eventually turn into frogs. I must say, I find them impossibly adorable with their squiggly little tails. But even cuter... when they sprout legs! Why, we can witness accelerated evolution in these squirmy little ones. Hoo, it makes me so emotional!','I caught a tadpole... It\'s just a tad small.','Fish64'),(76,2,'poisson',23,'tilapia',800,'Medium','Hard','Any weather',0,'Wherever the waters are warm, the tilapia can be found. It is a highly adaptable river fish. They mainly feed on algae, but they will also eat larvae and dead fish— or whatever fits in their mouths. I will confess that, as a growing owlet, I similarly defined food as \'anything that fits in my beak.\'','I caught a tilapia! It makes me happy-a!','Fish76'),(77,3,'poisson',66,'tuna',7000,'XX-Large','Very Hard','Any weather',50,'The tuna is a large ocean fish that can reach upwards of nine feet long. Besides its great size, it\'s notable for continuing to swim even when it\'s sleeping! Well, to be fair, if it doesn\'t keep swimming, it won\'t be able to breathe and will of course die... But sleep should be restful, eh wot! If I were the tuna I would feel very hard done by!','I caught a tuna! It\'s a little off-key!','Fish57'),(78,1,'poisson',75,'whale shark',13000,'X-Large w/Fin','Very Hard','Any weather',50,'The mighty whale shark is the largest species of fish in the world with specimens up to 60 feet long! Unlike many of their kin in the shark family, whale sharks are nonviolent, eating only plankton and such. They grow slowly and live long, relaxed lives of filter feeding and leisure in warm waters. So if you ever have to choose a fish as a roommate, you could do worse than the whale shark. Unless you can\'t swim.','Thar she blows! I caught a whale shark! I\'m tellin\' ya, it was thiiiiiiiiiiiiiiiiiiiis big!','Fish72'),(79,2,'poisson',21,'yellow perch',300,'Medium','Medium','Any weather',0,'The yellow perch is certainly worth squawking about. I find it a sight to behold! That jagged dorsal fin! Those brilliant stripes! Those glorious colours! Hoo, truly it is quite the specimen. I would be thrilled to witness it firsthand in its natural environment... But the yellow perch\'s peak season is winter, I\'m afraid. (So very afraid... of winter\'s biting chill...)','I caught a yellow perch! Those yellow birds have to sit somewhere!','Fish18'),(80,1,'poisson',53,'zebra turkeyfish',500,'Medium','Very Easy','Any weather',0,'The sheer brilliance and diversity found in the aquatic underworld never cease to amaze me. This zebra turkeyfish is as stunning to gaze upon as it is deadly. Those spines that are part of its defining physique are chock-full of venom. Fortunately, zebra turkeyfish are not susceptible to another\'s venom. Though solitary, I imagine they give one another a mean fin bump when passing each other by.','I caught a zebra turkeyfish! Land, air, water--make up your mind!','Fish44'),(81,7,'insecte',10,'agrias butterfly',3000,NULL,NULL,'Any except rain',20,'Some say the agrias butterfly is one of the most beautiful butterflies in the world. Bah, I say! BAH! They may have brightly colored wings, but the way they flutter and flitter...SO FOUL! In fact, the agrias butterfly flies so fast, it is quite a feat to catch one. I suppose I should congratulate you on your good fortune... But catching any bug seems a misfortune to me.','I caught an agrias butterfly! I wonder if it finds me disagrias-able?','Ins6'),(82,8,'insecte',69,'ant',80,NULL,NULL,'Any weather',0,'I warn you, the ant may be a small bug, but it finds scary strength in numbers. You see, the ant itself is the strongest creature in the world in relation to its size. One of these diminutive fiends can carry 50 times its own bodyweight! And if it wants to lift something even larger... Why, it simply calls on its ant friends to join the effort. Creepy cooperation, I say...','I caught an ant! TELL ME WHERE THE QUEEN IS!','Ins26'),(83,9,'insecte',14,'Atlas moth',3000,NULL,NULL,'Any weather',20,'The Atlas moth is a monstrous thing! Not only is it one of the largest moths in the world... The tips of its wings look rather like the heads of venomous snakes! Despite its largeness and loathsome looks, the adult Atlas moth lives only for a few days. It emerges from its cocoon without a mouth, you see...and so cannot eat. I feel for the poor thing...but it is still foul!','I caught an Atlas moth! I bet it never gets lost!','Ins10'),(84,10,'insecte',68,'bagworm',600,NULL,NULL,'Any weather',0,'The bagworm is, in fact, not a worm at all, but a caterpillar instead. The filthy fraud uses silk and leaves to spin a cozy bag for it to hide inside—hence the name. Some find it cute the way bagworms dangle from trees. But the truth is they\'re gluttonous monsters. These beasts love to stuff their bug- gullets full of leaves, devouring the very trees they hang upon. Wretched villains is what they are.','I caught a bagworm! Guess I\'m a bragworm!','Ins36'),(85,11,'insecte',34,'banded dragonfly',4500,NULL,NULL,'Any except rain',50,'The banded dragonfly is known for its black-and-yellow-striped body, as well as for its piercing green eyes. And it is those very eyes that help make dragonflies master hunters, you see. Alas, when one looks at me, I can\'t help but feel it is sizing me up for a meal! Hoot! The horrors! Look away, fiend!','I did it! Did you see that? I caught a banded dragonfly!','Ins24'),(86,12,'insecte',21,'bell cricket',430,NULL,NULL,'Any except rain',0,'The call of the bell cricket heralds the arrival of autumn. And I concede it is a rather pleasant sound. What I do NOT find pleasant is the way these things rub their strange wings together to make their song! Ick and blech! And to make matters worse, bell crickets have been known to shed two of their four wings! And they simply leave these wings where they fall, as if it were litter! I simply cannot abide such odious behavior.','I found a bell cricket! It would make a great bellhop!','Ins31'),(87,13,'insecte',49,'blue weevil beetle',800,NULL,NULL,'Any weather',0,'Yes, yes. The blue weevil beetle does come in beautiful shades of blue and green. The colors are so bright, some say it looks like a living jewel. But I say it looks like a weevil...and weevil rhymes with EVIL. Draw your own conclusions from there. Hoot! I certainly have!','I caught a blue weevil beetle! It\'s the lesser of blue weevils!','Ins80'),(88,14,'insecte',26,'brown cicada',250,NULL,NULL,'Any weather',0,'Cicadas are obnoxious insects. And not just brown cicadas, mind you...but all cicadas! They flex ribbed membranes on their torso called tymbals to make a loud snapping sound. So rude! Hoo! Yes, it is only the males who make the noise. Sometimes at a volume that can produce pain at close range! Appallingly inconsiderate, I must say...','I caught a brown cicada! Now it probably feels blue, cicada.','Ins17'),(89,15,'insecte',77,'centipede',300,NULL,NULL,'Any weather',0,'The centipede\'s name means \"100 legs.\" But I tell you now, that\'s a lie! These ugly bugs can have as few as 15 pairs of legs...or as many as 171. But because of how their bodies are segmented, they never have exactly 100! Hoo! It\'s true! You know what else is true? Centipedes are carnivorous, aggressive, and venomous! And their bite is quite painful too! HOO-rrible things, I say.','I caught a centipede! 99 more and I\'ll have a dollarpede!','Ins60'),(90,14,'insecte',31,'cicada shell',10,NULL,NULL,'Any weather',50,'Cicadas! The nerve! Not only are they loud, they leave their cicada shells lying about! When it\'s time for a cicada nymph to turn into an adult, you see, it clings to a tree and sheds its exoskeleton. Then it just leaves this shell of its former self hanging right there! Awful manners, really...and awfully terrifying too.','I found a cicada shell! I\'m glad the little guy came out of it!','Ins69'),(91,16,'insecte',47,'citrus long-horned beetle',350,NULL,NULL,'Any except rain',0,'The citrus long-horned beetle is a putrid pest and a grave threat to trees. Hoo! It\'s true! Adults possess powerful jaws and use them to chomp through hard wood and plant fibers with ease. The little larvae are no better, boring bullet-like holes into innocent trees with gusto—citrus trees especially. Voracious and vile, indeed!','I caught a citrus long-horned beetle! Orange you happy for me?','Ins39'),(92,17,'insecte',5,'common bluebottle',300,NULL,NULL,'Any except rain',0,'The common bluebottle is a type of swallowtail butterfly with a bright blue line running down its wings. They fly quite nimbly, it seems, and are thus quite difficult to catch. But seeing how they\'ve been known to slurp nutrients from MUD puddles... I simply CAN\'T imagine wanting to catch one myself. What awful breath!','I caught a common bluebottle! I\'ll put it in a rare green jar!','Ins72'),(93,17,'insecte',1,'common butterfly',160,NULL,NULL,'Any except rain',0,'The common butterfly would have you believe it is but a beautiful friend flitting prettily about the flowers. Bah, I say! They may seem innocent things with their pretty white wings, but they hide a dark side! The common butterfly caterpillar is called a cabbage worm, you see, and it\'s a most voracious pest. The ravenous beasts chew through cabbage, broccoli, kale and the like with a devastating gusto. And my feathers! Their green coloring is truly GROSS! A hoo-rrific hue, I say.','I caught a common butterfly! They often flutter by!','Ins0'),(94,12,'insecte',20,'cricket',130,NULL,NULL,'Any except rain',0,'I say, where shall I start with the cricket? Well, to begin with, they are mostly nocturnal creatures. And for that you day-loving diurnal types should be grateful! Hoo! It means you don\'t have to lay eyes upon their prickly legs or overly long antennae like us night owls! Of course, crickets are best known for the chirping sound they make by rubbing their wings together. Some find the noise lovely to listen to. Alas, it only serves to remind me of another unpleasant fact... Which is to say...you will find a cricket\'s ears right next to its knees! I\'ve gone weak in the knees at the mention of it!','I caught a cricket! What a chirp thrill!','Ins30'),(95,13,'insecte',59,'cyclommatus stag',8000,NULL,NULL,'Any weather',100,'The cyclommatus stag is known for its giant jaws, which can be even larger than its body. Its round eyes and silver color make it a beloved beetle. Though how one could love a beetle is beyond me. Imagine being pinched by those long jaws, and the pain it would cause! Ouch and ewww!','I caught a cyclommatus stag! Those mandibles are a mouthful!','Ins49'),(96,11,'insecte',35,'damselfly',500,NULL,NULL,'Any except rain',0,'The colorful damselfly is similar to its cousin, the dragonfly, though it tends to be smaller and thinner. But don\'t let the delicate looks fool you! Much like the dragonfly, the damselfly is a ruthless predator. It loves to catch flies midair and eat them, and has been known to snack on spiders it plucks from the web! In short, it is not a dinner guest I would recommend... And it is not a menu I could keep down.','I caught a damselfly! Now it\'s a damselfly in distress!','Ins81'),(97,11,'insecte',33,'darner dragonfly',230,NULL,NULL,'Any except rain',0,'The darner dragonfly is a very fast dragonfly, flying at speeds up to 40 miles per hour! They all have a distinctive green hue, but the males have blue underbellies while females have yellow ones. It all sounds pleasant enough, no? Well, did you know their young eat tadpoles...and even some small fish! Worse, these creepy carnivores will eat each other in a pinch! Grotesque does not describe it...','I caught a darner dragonfly! It better watch its mouth!','Ins23'),(98,18,'insecte',39,'diving beetle',800,NULL,NULL,'Any weather',0,'Ah, the dastardly diving beetle! Famous for its distinctive round shape...and its voracious appetite. This powerful predator uses thick back legs covered in hairs to paddle after its prey. And it uses suction cups on its front legs to grip its quarry for good. My own legs have gone weak thinking about it...','I caught a diving beetle! Now I\'m making a splash!','Ins28'),(99,9,'insecte',53,'drone beetle',200,NULL,NULL,'Any weather',0,'I must say, the drone beetle is like that boorish acquaintance who is much too loud for polite company. That is, it is a large bug with a square head and is so named for the droning noise it makes when it flies. Furthermore, it has hooks on its feet that help it to cling tightly to trees. HOOK FEET... How gauche!','I caught a drone beetle! Shouldn\'t you have more propellers?','Ins75'),(100,19,'insecte',50,'dung beetle',3000,NULL,NULL,'Any weather',0,'What can I say? The aptly-named dung beetle feeds on the feces of animals. Hoo! You heard right! This putrid pest rolls up balls of dung...and then rolls them away to dine on at a later date. As if that weren\'t atrocious enough, some dung beetles lay their eggs in the feces too! What a dreadful place to raise the young.','I caught a dung beetle! This species likes feces!','Ins40'),(101,12,'insecte',51,'earth-boring dung beetle',300,NULL,NULL,'Any weather',0,'Earth-boring dung beetles are considered quite handsome by some, thanks to their metallic luster. In fact, some even think them to be good omens and bringers of favorable fortune. But I must protest! These field- ravaging pests love to burrow under piles of dung and lay their eggs. They raise their young under DUNG! Need I say more? Ick. I think not.','I caught an earth-boring dung beetle! It\'s not boring at all!','Ins42'),(102,7,'insecte',9,'emperor butterfly',4000,NULL,NULL,'Any except rain',20,'The emperor butterfly is called the jewel of the forest. But its vivid blue hue... Ewww, let me tell you! The color does not come from a dye, but rather from light reflecting off layers of translucent scales. Yes, butterfly wings are covered in tiny scales! SCALES! Butterfly? Bah! More like snake of the sky!','I caught an emperor butterfly! It\'s not your average monarch!','Ins5'),(103,14,'insecte',30,'evening cicada',550,NULL,NULL,'Any weather',0,'The evening cicada certainly knows how to ruin a quiet moment. As the sun sets, it strikes up a sad song so sonorous, one can\'t hear one\'s own thoughts! I\'d feel sorry for its melancholy moods if it weren\'t so very vocal about how it feels. Ugh, please pipe down...','I caught an evening cicada! Better than an odding cicada...; I caught an evening cicada! This time it\'s WETTER than an odding cicada.','Ins20'),(104,11,'insecte',36,'firefly',300,NULL,NULL,'Any except rain',0,'The firefly isn\'t a fly at all! It is a beetle, you see—and one known for its ghastly glowing backside. This light is called \"bioluminescence\" and it is caused by...by...a chemical reaction in the rump. Males flash about in the night sky to attract females, while their larvae turn on the glow to put off predators. Speaking of their yucky young, firefly larvae love to dine on snails! Hoo! Ewwww!','I caught a firefly! I\'m on fire now!','Ins41'),(105,20,'insecte',74,'flea',70,NULL,NULL,'Any weather',0,'Allow me to be blunt. The flea is foul! It is also disgusting, repugnant, and vile! Hoo! But I digress... This horrid pest sucks the blood of humans and animals. In fact, it is the flea\'s own saliva that makes us itch! And did you know their legs are so strong, they can jump more than 50 times their body length? So you see, it\'s all too easy for a flea to jump from you to me! I itch at the very thought.','I caught a flea! The curse is lifted.','Ins56'),(106,21,'insecte',72,'fly',60,NULL,NULL,'Any weather',0,'The foul fly is quite the disquieting creature. I tell you, it tastes its food with its feet! Yeep! In fact, when flies rub their legs together, they do so to get rid of debris blocking their taste receptors. And did you know, their hairy toes release a sticky goo so they can walk on any surface? Even your ceiling! This gross goo gets on your food too!','I caught a fly! I was just wingin\' it...','Ins59'),(107,14,'insecte',28,'giant cicada',500,NULL,NULL,'Any weather',20,'The giant cicada is rather aptly named. That is, it\'s a truly enormous bug. Ugh! These beasts spend most of their lives underground where they gorge on tree roots. But once they emerge, they make an awful racket. In fact, some say their song sounds like a shrieking siren. I would rather listen to nails on a chalkboard.','I caught a giant cicada! I guess it\'s PRETTY big...; I caught a giant cicada! Guess it doesn\'t feel like singing in the rain!','Ins65'),(108,9,'insecte',57,'giant stag',10000,NULL,NULL,'Any weather',50,'It is said the giant stag is a popular pet among bug enthusiasts. Though how one might consider oneself enthusiastic about bugs is quite beyond me... But I digress. Giant stags look fearsome with their enormous curved mandibles. But in truth, they\'re really quite cowardly. Oh how they love to hide away in rotting wood, only to reveal themselves under the cover of dark. Hoot! I shall never turn off the lights again!','Whoaaa! I caught a giant stag! I\'m gonna need way bigger pockets...','Ins47'),(109,18,'insecte',40,'giant water bug',2000,NULL,NULL,'Any weather',50,'How to put this gently? Ah yes... BEWARE the giant water bug! I tell you, this vicious predator has been known to attack fish, frogs, and even snakes! SNAKES! Truth be told, no one is safe! Its nickname is \"the toe-biter,\" for goodness sakes! Now, one final fact before I faint... The gruesome bug uses its nose...to inject its prey...with digestive juices. Hoo... Must stop thinking about...the unthinkable.','I caught a giant water bug! It should\'ve stayed in the water!','Ins76'),(110,13,'insecte',61,'giraffe stag',12000,NULL,NULL,'Any weather',100,'The giraffe stag beetle is a bug of preposterous proportions. Not only is its body rather large, it has two long, jagged jaws that can put it over five inches in size! The giraffe stag beetle\'s long jaws have been compared to the long neck of the giraffe...hence the name. But I say such comparisons are a stretch. Giraffe necks are NOT lined with spikes! If I were a giraffe, I would protest.','I caught a giraffe stag! Does that make it a longhorn?','Ins77'),(111,13,'insecte',60,'golden stag',12000,NULL,NULL,'Any weather',100,'Yes. Yes. The golden stag beetle is quite the prize thanks to its metallic gold coloring. But let me speak plainly... The golden stag is NOT made of gold. It is made of BUG, through and through. And thus it is vile! Golden stag? Bah! Gross stag is more like it.','Wooooow! I caught a golden stag! Does this mean I can retire?','Ins50'),(112,13,'insecte',54,'goliath beetle',8000,NULL,NULL,'Any weather',100,'Hoo! Ewww! The goliath beetle is a colossal creature that can grow up to four inches long. Yes, they love to sup on sap and pollen, and frolic among the flowers. But did you know, the goliath beetle has a horn upon its head that it uses to fight its foes? And picture this... Each one of this behemoth\'s legs ends in pincers! Deep...calming...breaths...','I caught a goliath beetle! Am I a legend or what?','Ins55'),(113,12,'insecte',19,'grasshopper',160,NULL,NULL,'Any except rain',0,'Grasshoppers are known for making a \"chirping\" sound. Though it doesn\'t sound like chirping to me... They make this rude racket by rubbing their hind legs against their wings. And though they eat seeds and pollen, they sometimes prey on smaller insects too. I say! Such violent table manners should not be tolerated! Horrible hoppers.','I caught a grasshopper! They\'re a grass act!','Ins32'),(114,7,'insecte',7,'great purple emperor',3000,NULL,NULL,'Any except rain',50,'The great purple emperor lives high in the treetops and is renowned for its pretty purple-hued wings. Its impressive bird-like wingspan and elusive nature have made it a favorite among butterfly aficionados. But truth be told, the so-called great purple emperor has some not-so-great personal peculiarities. For one...it has two horrid HORNS upon its head when it is in its caterpillar form. For two...it has been known to dine on feces and animal carcasses! Hoo! That\'s why I call it the Emperor of EWWW!','I caught a great purple emperor! Its purple reign is over now!','Ins74'),(115,22,'insecte',70,'hermit crab',1000,NULL,NULL,'Any weather',0,'The hermit crab is not an insect... Though it most certainly resembles one. Blech! It looks much like a spider—what with its creepy eyes and crawly legs—but is, in fact, a crustacean. As such, the hermit crab has 10 legs and also wears a shell. But it doesn\'t grow this shell itself. It slips its soft body into shells left behind by snails, you see, and moves into ever-larger ones as it grows. Talk about a strange way to make a home.','I caught a hermit crab! I think it wanted to be left alone!','Ins66'),(116,7,'insecte',24,'honeybee',200,NULL,NULL,'Any except rain',0,'Did you know it takes a team of honeybees working together to transform flower nectar into honey? Indeed, forager bees suck nectar from flowers into their \"honey stomachs\" and then fly it to the hive. Hive bees then chew the substance and spit it into the honeycomb, fluttering their wings to dry it out. Yes, you could say honey is a tasty tribute to the hard work of the humble honeybee. Oh! Oh my! You mustn\'t confuse my lengthy description for admiration! At the end of the day, honeybees are still insects, and thus still ghastly! A wee bit less ghastly than most, I admit.','I caught a honeybee! Ah, sweet success!','Ins11'),(117,13,'insecte',63,'horned atlas',8000,NULL,NULL,'Any weather',100,'Beware the horned atlas! I tell you, this rhinoceros beetle is known for its violent temperament! The males use the three large horns on their heads to fight amongst each other for dominance. But it is their young that truly give me the cold sweats. You see, their larvae grow quite large and, worst of all...they bite! It is the stuff of nightmares, I say.','I caught a horned atlas! I didn\'t even need a map!','Ins52'),(118,9,'insecte',62,'horned dynastid',1350,NULL,NULL,'Any weather',0,'The horned dynastid\'s head is shaped like a samurai warrior\'s helmet, hootie-hoo! It would be a most impressive fact if their large size wasn\'t so horrifying! Adult males use their huge horned heads for fighting and digging, while the females have no such need. As for their larvae and pupae, they too are quite large and feed on rotting wood at a tremendous pace. A foul feast, indeed!','I caught a horned dynastid! I\'d hate to hear it honk that schnoz!','Ins51'),(119,13,'insecte',64,'horned elephant',8000,NULL,NULL,'Any weather',100,'The horned elephant beetle certainly lives up to its namesake. Not only does the horn on its head resemble the trunk of an elephant... It is also one of the heaviest beetles in the world! Size aside, allow me to reveal the real reason I find horned elephant beetles so repugnant... Their backs are covered in a fine coat of hair! Hirsute beetles! Hoot! The horror!','I caught a horned elephant! I think it\'s too small to ride...','Ins53'),(120,13,'insecte',65,'horned hercules',12000,NULL,NULL,'Any weather',100,'The horned hercules is not only known for its tremendous strength, but for its size as well. It can grow up to seven inches long and has powerful pincers covered in hair that help with gripping! As if this weren\'t ghastly enough, these behemoth beetles let loose a foul odor that fends off enemies... And offends my sense of smell.','I caught a horned hercules! Guess I was stronger!','Ins54'),(121,16,'insecte',45,'jewel beetle',2400,NULL,NULL,'Any except rain',20,'The green shimmer of the jewel beetle\'s wings is nothing short of nauseating...yes? No? Well, so says you. Though...jewel beetles were once prized by collectors who turned their iridescent wings into pretty jewelry. Why anyone would want to wear bug parts on their body is beyond me. Fashion foul indeed.','I caught a jewel beetle! It\'s a real gem!','Ins44'),(122,23,'insecte',43,'ladybug',200,NULL,NULL,'Any except rain',0,'Yes. Yes. Ladybugs are quite beloved thanks to their tiny round shape and adorable spots. To that I say BAH! The fact of the matter is, some have stripes instead of spots. And SOME have no markings at all! No, I shall never understand why it is said that when a ladybug lands on you...you\'ll have good luck. I shall only have a fainting spell.','I caught a ladybug! Sorry to disturb you, ma\'am.','Ins37'),(123,12,'insecte',16,'long locust',200,NULL,NULL,'Any weather',0,'As if the average locust weren\'t large enough...we must suffer the long locust too! The wretched beasts are known for their unusually long hind legs as well as their elongated heads. But that is hardly the long locusts\' worst trait... I tell you, they spit brown goo when they\'re scared!','I caught a long locust! Or, as I call it, a looooocust.','Ins13'),(124,7,'insecte',15,'Madagascan sunset moth',2500,NULL,NULL,'Any except rain',20,'The Madagascan sunset moth is said to be the most beautiful moth in the world...a sentiment even I can\'t deny. While most moths are nocturnal, this one flutters about during the day, making good use of the light. That is, when the daylight reflects off its wings, a kaleidoscope of colors are revealed! Oh! Eh...too bad it has such startling red feet as a caterpillar. I might have found it almost tolerable otherwise. Almost, but not quite.','I caught a Madagascan sunset moth! Wow, you\'re not from around here!','Ins79'),(125,23,'insecte',42,'man-faced stink bug',1000,NULL,NULL,'Any except rain',20,'Never mind this stink bug\'s smell. What you have here is a bug...with a FACE...on its BACK!! Wot-wot! Simply put, the man-faced stink bug has markings on its shell that resemble a human face. Once you notice this face, you cannot UN-notice it. Indeed, this face might haunt you forever. At least the face will distract you from the stink.','I caught a man-faced stink bug! Reminds me of my uncle!','Ins78'),(126,23,'insecte',22,'mantis',430,NULL,NULL,'Any except rain',0,'Hoo! Don\'t let the mantis\'s angelic pose fool you...for it is truly monstrous. The mantis is known for its large size and tremendous strength...and for sickle-like arms that pack a punch. And though they tend to eat bugs and spiders...mantises have been known to dine on small animals too! And those eerie eyes! Oh my! Did you know it has five of them! Two big ones and three small! I shall faint if I think on it further...','I caught a mantis! Man, \'tis so cool!','Ins15'),(127,12,'insecte',17,'migratory locust',600,NULL,NULL,'Any weather',20,'Ah yes, the lone migratory locust. It seems like such a harmless hopper as it bounces about in the grass. But beware! When these pests band together and travel in swarms, they leave devastation in their wake! Migratory locusts have gathered by the millions throughout history, wiping out crops and causing famine. That\'s why I always say, \"Never let a locust hang out with its friends!\". That is precisely how a plague begins.','I caught a migratory locust! Things just went south for this guy!','Ins14'),(128,9,'insecte',56,'miyama stag',1000,NULL,NULL,'Any weather',0,'The miyama stag has protrusions on its head that resemble ears... And yet, the ugly lumps are not ears! It is, however, called a \"stag\" beetle because of the large, deer-like horns upon its head. And the word \"miyama\" in its name means \"deep mountain\" in Japanese. Feel free to call it what you like. I will simply call it DISGUSTING. \"Disgusting stag beetle\" does have a ring.','I caught a miyama stag! Its mandibles are jaw-dropping!','Ins45'),(129,24,'insecte',37,'mole cricket',500,NULL,NULL,'Any weather',0,'Be warned, there is nowhere one might hide from the mole cricket. This plump pest has powerful front claws made for digging holes, and oh how it loves to burrow underground! A cousin to the grasshopper, it also has wings and can easily take to the air. And I swear this on my pinfeathers... Some have even been seen walking on water! Oh mercy, I may need a moment. This is making me feel rather woozy...','I caught a mole cricket! I really dug it!','Ins33'),(130,7,'insecte',8,'monarch butterfly',140,NULL,NULL,'Any except rain',0,'Did you know the monarch butterfly migrates south for the winter and returns north for the summer? Indeed, these horrid orange beasties do not tolerate the cold and travel 3,000 miles to escape the winter. During the journey, they cluster together in trees by the thousands just to stay warm. Imagine! Hordes of the foul flittering fiends huddled together in one place! If only they\'d put on tiny coats instead.','I caught a monarch butterfly! Guess the butterflies are a democracy now!','Ins4'),(131,17,'insecte',73,'mosquito',130,NULL,NULL,'Any except rain',0,'As everyone knows, the mosquito is a vampiric pest that sucks blood from innocent bystanders. But did you know that only the females suck blood? Hoo! It\'s true! They need it to make their eggs. When they sink their snout into our skin, they inject us with a saliva that helps them slurp up their meal. It\'s that saliva that makes us itch and scratch, you know. Hoo! So rude!','I caught a mosquito! It\'s itching for a fight!','Ins58'),(132,25,'insecte',13,'moth',130,NULL,NULL,'Any except rain',0,'Many think the moth is strictly a nocturnal creature. Alas, no! These frightful fluttering beasts have been known to haunt the daylight and twilight hours too. Thus, there is no time of day one might escape the moth trait I dislike most of all—those feathery antennae! The mere thought of them gives my feathers goosebumps. And I\'m no goose.','I caught a moth! And I had a ball doing it!','Ins9'),(133,26,'insecte',23,'orchid mantis',2400,NULL,NULL,'Any except rain',20,'The orchid mantis is a bug whose brilliant colors and petal-shaped limbs give it the look of a flower. This masterful mimicry allows it to hide from predators in among the orchids. But oh this fraudulent flower! It lures other insects in to drink its nectar... And makes a meal of them instead! Imagine! To behold a beautiful bud... only to discover it\'s a bug instead! A repulsive revelation indeed!','I caught an orchid mantis! Our friendship is blooming!','Ins16'),(134,7,'insecte',6,'paper kite butterfly',1000,NULL,NULL,'Any except rain',0,'With its black-and-white-striped wing pattern, the paper kite butterfly is both elegant and pretty... PRETTY POISONOUS I MEAN! Hoo dear! Where was I? Oh yes... Even this butterfly\'s black-and-white-striped larva and little golden pupae are toxic to predators. Indeed, the paper kite butterfly\'s foul flavor is famous, and thus birds, in particular, steer clear of the fiends. THIS bird most of all!','I caught a paper kite butterfly! Do I read it, fly it, or spreadit on toast?','Ins73'),(135,27,'insecte',4,'peacock butterfly',2500,NULL,NULL,'Any except rain',20,'Pretty as a peacock? Bah, I say! The wings of the peacock butterfly may have a pattern similar to that of the beautiful bird... But its forewings are also often covered in a dark, velvety hair! You heard right! HAIRY wings! A hair-raising revelation indeed!','I caught a peacock butterfly! Now it\'s my turn to strut my stuff!','Ins3'),(136,15,'insecte',76,'pill bug',250,NULL,NULL,'Any weather',0,'Blech, the pill bug! Children delight at the way these beasts roll into balls when poked... But the appeal is utterly lost on me. One look at their leggy undersides... Hoo! Ewww! How they wriggle! Young pill bugs shed their exo- skeletons as they grow, and in doing so, sprout another pair of legs. As if 12 appendages weren\'t alarming enough! Yuck, I say. Yuck!','I caught a pill bug! That\'s a tough act to swallow!','Ins57'),(137,18,'insecte',38,'pondskater',130,NULL,NULL,'Any weather',0,'Putrid pondskaters! They walk on water, you know...which is most preposterous! It is a trick they perform by secreting oil onto the hairs of their feet. To which I say BLEEECH! And one must wonder... What will they do next? Walk on air? Walk through walls? Perish the thought...','I caught a pondskater! Wonder if it can do a pond ollie...','Ins27'),(138,7,'insecte',12,'Queen Alexandra\'s birdwing',4000,NULL,NULL,'Any except rain',50,'Hoo! The horror! This behemoth butterfly may be called a Queen Alexandra\'s birdwing... But I call it the Queen of My Nightmares! It is huge! Indeed, the world\'s hugest. No butterfly can best its foot-long wingspan. The larvae alone grow to more than 4 inches. As if that weren\'t appalling enough...they\'re poisonous! Murderous monsters, indeed!','I caught a Queen Alexandra\'s birdwing! That\'s a feather in my cap!','Ins8'),(139,9,'insecte',58,'rainbow stag',6000,NULL,NULL,'Any weather',50,'Rainbows are beautiful things, I\'m sure we all agree. But rainbow stag beetles? Bleech! Yes, yes, this beetle\'s back and belly shine with a pretty rainbow- colored luster. But that does not change the fact this bug has large pincers on its face and loves to pick a fight! If one can wish upon a rainbow, then I wish to stay far away from the rainbow stag. Perhaps I\'ve picked the wrong profession.','I caught a rainbow stag! Its rainbow armor is so shiny!','Ins48'),(140,7,'insecte',11,'Rajah Brooke\'s birdwing',2500,NULL,NULL,'Any except rain',20,'Did you know that the repulsive Rajah Brooke\'s birdwing loves to luxuriate in hot-springs water? It\'s true! Hoo! The males gather in groups to sip the moisture while the females hide in jungle trees. And though they dress to impress in red and green, these fluttering fiends are not just stylish... They\'re also quite malicious! Their little larvae pack a poisonous punch that\'s supposed to protect them from predators... But I suspect more diabolical designs.','I caught a Rajah Brooke\'s birdwing! Nothing else I\'d rajah be doing!','Ins7'),(141,11,'insecte',32,'red dragonfly',180,NULL,NULL,'Any except rain',0,'I won\'t deny that the wretched red dragonfly is an elegant aeronaut. It manipulates its four wings quite uniquely so it can hover and maneuver through the air with ease. But the veins on its wings! What ghastly things! One can\'t help but gasp at the sight of them... Appalling aerodynamics, indeed!','I caught a red dragonfly! Didn\'t even have to roll for initiative!','Ins22'),(142,12,'insecte',18,'rice grasshopper',400,NULL,NULL,'Any weather',0,'In point of fact, rice grasshoppers are an awful pest! They devour rice plants and wipe out the crucial crop. But revenge is sweet! These bugs are edible, you see, and so some folks eat them as way to get rid of them. When boiled in soy sauce, rice grasshoppers are quite tasty, it\'s said. Though why anyone would put an insect in their mouth is beyond me. The mere thought gives me the gags!','I caught a rice grasshopper! I\'ve been looking for a gluten-free alternative...','Ins67'),(143,14,'insecte',27,'robust cicada',300,NULL,NULL,'Any weather',0,'The robust cicada got its name from the chirping sound it makes, which is said to be quite...well...robust. But \"robust\" hardly describes it. Abrasive! Bombastic! Cacophonous! That\'s more like it! Beside the horrid caterwauling, this bug is known for its long wings, short body, and green coloring. But looking at a robust cicada is just as unpleasant as listening to one. My eyes AND my ears are offended.','I caught a robust cicada! It DOES seem pretty lively!; I caught a robust cicada! Not so energetic in the rain, huh?','Ins18'),(144,16,'insecte',48,'rosalia batesi beetle',3000,NULL,NULL,'Any except rain',20,'The rosalia batesi beetle is a type of longhorn beetle, so named for the long antennae upon its head. But did you know that longhorn beetles often grow antennae longer than their very own bodies, wot wot? As if this weren\'t odious enough, look closely and you will find these antennae...are covered in tufts of hair! Best not look closely, I say.','I caught a rosalia batesi beetle! That\'s easier to do than say!','Ins82'),(145,9,'insecte',55,'saw stag',2000,NULL,NULL,'Any weather',0,'The saw stag got its name from the shape of its pincers. That is, its pincers look like jagged saws! And I tell you, the bigger the beetle, the more saw-like teeth its giant jaws have. I say the saw stag seems more at home in a horror film than in nature. I have terrified myself just talking about it.','I caught a saw stag! Now I can\'t unsee it!','Ins46'),(146,9,'insecte',52,'scarab beetle',10000,NULL,NULL,'Any weather',50,'Collectors consider the scarab beetle quite the prize, thanks to its shiny metallic shell. But did you know this bug has no nose and uses its antennae to sense smells instead? In fact, the scarab beetle\'s plated antennae are quite unique and set it apart from other beetles. But ALL antennae are equally awful in my book.','I caught a scarab beetle! It\'s just a dung beetle with better hobbies.','Ins43'),(147,12,'insecte',80,'scorpion',8000,NULL,NULL,'Any weather',0,'The scorpion...how should I put this? Those legs! Those pincers! That tail! And that venomous stinger! It\'s as if someone took all the most awful insect parts...and put them together to make the scorpion! All scorpions are venomous, you know! Though I understand that only a few kinds are truly deadly. I fear I might die just thinking about it.','I caught a scorpion! It was a sting operation!','Ins63'),(148,28,'insecte',75,'snail',250,NULL,NULL,'Rain only',0,'Snails are not insects, I\'ll admit. But they\'re just as revolting to me. Snails are mollusks, you see, and are born wearing shells they cannot remove. Instead, their shells get bigger and bigger as they grow. Hoo! They must get heavy, don\'t you know! I suppose that\'s why they need a trail of mucus to move about. A truly foul form of transportation.','I caught a snail! It\'s...not much to brag about.','Ins29'),(149,10,'insecte',78,'spider',600,NULL,NULL,'Any weather',0,'The spider is renowned for having eight eyes and eight legs... WHICH IS SIX TOO MANY, I SAY! Oh dear. I do apologize. Now where was I? Most spiders are carnivorous. In fact, some will eat creatures several times larger than themselves. To catch their prey, many of these ruthless predators spin sticky webs of surprising strength. Worse yet, they\'ve also been known to ambush their victims, and some even chase down their meals! All this talk about the feeding habits of spiders... I\'m feeling quite queasy. Hoot! The horror!','I caught a spider! I spied \'er first!','Ins61'),(150,23,'insecte',41,'stinkbug',120,NULL,NULL,'Any except rain',0,'I daresay the name says it all... Stinkbugs are known for their stench. Hoo! Peeyew! As it happens, these crop-eating pests use straw-like mouths to pierce plants and drink the juices. And when threatened, they use a smelly chemical in their belly to release their odious odor! Hoo! How DO they live with themselves?','I caught a stinkbug! It lives up to its name!','Ins64'),(151,12,'insecte',79,'tarantula',8000,NULL,NULL,'Any weather',0,'As giant spiders go, the tarantula is said to be quite docile. But have you ever seen such foul fuzziness?! It is a fact, tarantulas have barbed belly hair! I say again...BARBED. BELLY. HAIR! These awful arachnids let loose their spiky, itchy hairs to protect themselves from predators. But seeing how tarantulas also prey on frogs, mice, and even birds, one must ask... Who needs protecting from whom?! Hoo! Who indeed!','I caught a tarantula! This situation just got hairy!','Ins62'),(152,12,'insecte',44,'tiger beetle',1500,NULL,NULL,'Any except rain',20,'The tiger beetle is extremely fleet of foot, though it runs in a rather peculiar way. That is, it sprints, then stops, then sprints again...using these speedy maneuvers to run down its prey. You see, the tiger beetle—like a real tiger—is a powerful predator. The mere thought of it giving chase gives me the willies. Tigers are terrifying at any size.','I caught a tiger beetle! I pounced first!','Ins70'),(153,17,'insecte',3,'tiger butterfly',240,NULL,NULL,'Any except rain',0,'Tiger butterflies are known for their majestic wings, which many consider quite beautiful. Truth be told, I find them monstrous! Those strange striped patterns... They give this owl the goose bumps! And while you may imagine young tiger butterfly larvae to look like lovely green caterpillars...it\'s not so! Why, when tiger butterflies are but babes, they\'re covered in unsightly white, brown, and black spots. In this way, they camouflage themselves as...as...bird droppings! Putrid pests, indeed!','I caught a tiger butterfly! I\'ve earned my stripes!','Ins2'),(154,16,'insecte',46,'violin beetle',450,NULL,NULL,'Any except rain',0,'The violin beetle gets its name from its shape. That is, SOME think it resembles the stringed instrument. If you ask me, this is an insult to violins! With its flat body and small head, the violin beetle looks like nothing but a repulsive bug, plain and simple. In fact it is so repulsive, it oozes a foul liquid when frightened! Ugh! This insect strikes a sour note indeed.','I caught a violin beetle! Apparently I\'m as fit as a fiddle!','Ins38'),(155,14,'insecte',29,'walker cicada',400,NULL,NULL,'Any weather',0,'The walker cicada is quite the noisy thing. I tell you, this impolite pest simply canNOT abide the quiet. In the heat of summer, the male strikes up a strange rattling song, hoping to woo a mate. When other male cicadas hear this rhythmic racket, they join right in... As if it were a sing-along! My head aches at the thought of it.','I caught a walker cicada! Pffft... I walk all the time and no one calls me \"Walker ...\"; I caught a walker cicada! It must hate getting its feet wet.','Ins19'),(156,29,'insecte',67,'walking leaf',600,NULL,NULL,'Any weather',20,'What a fraud! What a phony! The walking leaf is, in fact, the very embodiment of a lie! This master mimic looks like a tree leaf all the way down to the tiniest details. In fact, this bug has been known to sway to and fro as it walks...just so it looks like a leaf blown by the wind! And the fakery works! These insects look so much like leaves that even leaf-eating insects nibble on them! Lying liars, indeed!','I caught a walking leaf! It seems to be taking it in stride!','Ins34'),(157,9,'insecte',66,'walking stick',600,NULL,NULL,'Any weather',20,'The walking stick looks just like a twig, does it not? Hoo! It even has knots like a real twig would! These bashful bugs mimic plants in this way to hide from predators. A noble goal, you might say. But though the deceptive wretches fool some, they do not fool me! I see these bugs for what they are... Monsters, plain and simple! I say, did you know that walking sticks can grow to two feet long?! Imagine running into one! Surely I would faint.','I caught a walking stick! Check out its walking schtick! Look, these are the jokes, OK?','Ins35'),(158,30,'insecte',25,'wasp',2500,NULL,NULL,'Any weather',0,'Hoo! Allow me to share a fact with you! Wasps are sometimes called \"meat bees\" because... They. Eat. MEAT! MEAT! Of almost any sort! Surely you\'ve seen what a menace they make of themselves at picnics. \'Tis hardly the worst of it, wot wot! Aggressive predators with venomous stingers, wasps not only hunt and eat other insects... they paralyze their prey, then drag their victims home ALIVE, leaving them for their larva to feed upon. Suddenly a simple sting seems quite tolerable.','I caught a wasp! That\'s gotta sting...','Ins12'),(159,31,'insecte',71,'wharf roach',200,NULL,NULL,'Any weather',0,'The wharf roach is an omnivore, which is merely a polite way of saying it will eat almost anything. This skittering scavenger and its uncouth appetite help keep beaches clean, it\'s said. But I dare say, their long antennae and bulging eyes turn MY stomach. Unappetizing indeed...','I caught a wharf roach! This water-loving roach has no pier!','Ins71'),(160,17,'insecte',2,'yellow butterfly',160,NULL,NULL,'Any except rain',0,'Allow me to enlighten you... The yellow butterfly is named for its yellow wings. Need I say more? If I must, then allow me to note that the female yellow butterfly can lay up to 600 eggs at a time! Bleech! And their creepy crawly caterpillars just love to chomp on clover plants. A recipe for disaster, I say. Just imagine reaching for a four-leaf clover, only to touch a larva instead! Yuck! The worst of luck!','I caught a yellow butterfly! Shouldn\'t all BUTTERflies be yellow?','Ins1');
